import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Закон Самостоятельного Роста и Саморазвития","description":"","frontmatter":{},"headers":[],"relativePath":"ru/07-自生自长进化法则.md","filePath":"ru/07-自生自长进化法则.md"}'),i={name:"ru/07-自生自长进化法则.md"};function h(l,t,o,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="закон-самостоятельного-роста-и-саморазвития" tabindex="-1">Закон Самостоятельного Роста и Саморазвития <a class="header-anchor" href="#закон-самостоятельного-роста-и-саморазвития" aria-label="Permalink to &quot;Закон Самостоятельного Роста и Саморазвития&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>07</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Самостоятельный рост, Автономная эволюция, Внутренний импульс, Уважение к ритму, Развитие потенциала</td></tr></tbody></table><h2 id="i-базовое-определение-закона-самостоятельного-роста-и-саморазвития" tabindex="-1">I. Базовое определение закона Самостоятельного Роста и Саморазвития <a class="header-anchor" href="#i-базовое-определение-закона-самостоятельного-роста-и-саморазвития" aria-label="Permalink to &quot;I. Базовое определение закона Самостоятельного Роста и Саморазвития&quot;">​</a></h2><p>Самостоятельный рост и саморазвитие — один из центральных эволюционных законов Симбиотической Цивилизации Якоря: эволюция каждой жизни должна основываться на её собственной внутренней автономной воле и естественном ритме как на фундаментальной движущей силе, а внешняя среда и институты должны обеспечивать поддержку и гарантии этой автономной эволюции, а не принудительно вмешиваться или форсировать рост. «Самостоятельный рост» подчёркивает, что движущая сила эволюции исходит от самой жизни; «саморазвитие» подчёркивает, что ритм эволюции следует собственным законам жизни.</p><p>Закон резко контрастирует с «принудительной эволюцией» хищничества. Хищничество часто достигает быстрой, но искажённой эволюции через пожирание Истока других, принудительное наполнение энергией, контроль души и другие средства. Хотя такая эволюция может краткосрочно повысить уровень, в долгосрочной перспективе она разрушает собственный эволюционный фундамент жизни, ведя к нечистому Истоку, нестабильным уровням и повреждённому разуму. Закон настаивает: по-настоящему прочная эволюция должна вырастать изнутри самой жизни, изнутри наружу.</p><h2 id="ii-теоретические-основания-закона" tabindex="-1">II. Теоретические основания закона <a class="header-anchor" href="#ii-теоретические-основания-закона" aria-label="Permalink to &quot;II. Теоретические основания закона&quot;">​</a></h2><p>Установление закона основано на глубоком понимании законов эволюции жизни:</p><h3 id="_2-1-автономия-жизни-—-фундаментальная-движущая-сила-эволюции" tabindex="-1">2.1 Автономия жизни — фундаментальная движущая сила эволюции <a class="header-anchor" href="#_2-1-автономия-жизни-—-фундаментальная-движущая-сила-эволюции" aria-label="Permalink to &quot;2.1 Автономия жизни — фундаментальная движущая сила эволюции&quot;">​</a></h3><p>Каждая жизнь обладает внутренней эволюционной волей и потенциалом, и эта автономия — самая фундаментальная и устойчивая движущая сила эволюции. Внешние стимулы и поддержка могут зажечь эту автономию, но не могут заменить её. Когда жизнь практикует по собственному стремлению и выбору, сосредоточенность, креативность и выносливость её культивации намного выше, чем при принуждении или индуцировании.</p><h3 id="_2-2-каждая-жизнь-имеет-уникальныи-эволюционныи-ритм" tabindex="-1">2.2 Каждая жизнь имеет уникальный эволюционный ритм <a class="header-anchor" href="#_2-2-каждая-жизнь-имеет-уникальныи-эволюционныи-ритм" aria-label="Permalink to &quot;2.2 Каждая жизнь имеет уникальный эволюционный ритм&quot;">​</a></h3><p>Разные жизни из-за различий в расовых чертах, индивидуальных дарованиях, среде роста и зрелости разума имеют разные эволюционные ритмы. Одним подходят быстрые прорывы, другим — медленное накопление; одни достигают высоких уровней в юности, другие расцветают поздно. Закон уважает это различие и не требует, чтобы все жизни эволюционировали по единому расписанию.</p><h3 id="_2-3-принудительное-вмешательство-разрушает-естественныи-фундамент-эволюции" tabindex="-1">2.3 Принудительное вмешательство разрушает естественный фундамент эволюции <a class="header-anchor" href="#_2-3-принудительное-вмешательство-разрушает-естественныи-фундамент-эволюции" aria-label="Permalink to &quot;2.3 Принудительное вмешательство разрушает естественный фундамент эволюции&quot;">​</a></h3><p>В истории культивации много случаев, показывающих, что «быстрая эволюция», достигаемая принудительным наполнением энергией, пересадкой Истока, контролем души и другими средствами, часто сопровождается тяжёлыми последствиями: нереально взвешенные уровни, нечистый Исток, размножающиеся внутренние демоны, укороченная жизнь и даже отклонение от пути. Это объясняется тем, что навязанная извне сила не полностью слилась с собственным Истоком жизни, создавая эффект «отторжения чужеродного тела». Хотя самостоятельная эволюция может быть медленнее, каждый шаг прочен и устойчив, с глубоким фундаментом.</p><h2 id="iii-практические-принципы-закона" tabindex="-1">III. Практические принципы закона <a class="header-anchor" href="#iii-практические-принципы-закона" aria-label="Permalink to &quot;III. Практические принципы закона&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Принцип</th><th>Смысл</th><th>Практические требования</th></tr></thead><tbody><tr><td>Принцип автономного выбора</td><td>Практик имеет право самостоятельно выбирать систему культивации, эволюционный путь и ритм</td><td>Не принуждать к выбору конкретных систем; не устанавливать единые графики прорывов</td></tr><tr><td>Принцип внутреннего импульса</td><td>Движущая сила культивации должна исходить из собственного стремления и интереса практика</td><td>Образование и наставничество направлены на зажигание внутреннего интереса, а не на наказание или подкуп</td></tr><tr><td>Принцип уважения ритма</td><td>Уважать уникальный эволюционный ритм каждого практика</td><td>Не дискриминировать и не бросать медленно прогрессирующих; предоставлять индивидуальные планы поддержки</td></tr><tr><td>Принцип приоритета фундамента</td><td>Устойчивость эволюции важнее скорости</td><td>Поощрять закладывание прочного фундамента; не поощрять жертву фундаментом ради быстрых прорывов</td></tr><tr><td>Принцип терпимости к ошибкам</td><td>Разрешать практикам ошибаться и делать крюки в эволюции</td><td>Создавать механизмы терпимости; давать возможности исправления и корректировки</td></tr><tr><td>Принцип самореализации</td><td>Конечная цель эволюции — самореализация жизни, а не внешние стандарты</td><td>Не считать высоту уровня единственным критерием эволюционного успеха</td></tr></tbody></table><h2 id="iv-отношения-между-самостоятельным-ростом-и-внешнеи-поддержкои" tabindex="-1">IV. Отношения между самостоятельным ростом и внешней поддержкой <a class="header-anchor" href="#iv-отношения-между-самостоятельным-ростом-и-внешнеи-поддержкои" aria-label="Permalink to &quot;IV. Отношения между самостоятельным ростом и внешней поддержкой&quot;">​</a></h2><p>Закон не означает «самозатухание» или «пустить на самотёк». Напротив, самостоятельный рост требует хорошей внешней среды и институциональной поддержки для полной реализации. Симбиотическая цивилизация предоставляет следующие системы поддержки:</p><h3 id="_4-1-информационная-поддержка" tabindex="-1">4.1 Информационная поддержка <a class="header-anchor" href="#_4-1-информационная-поддержка" aria-label="Permalink to &quot;4.1 Информационная поддержка&quot;">​</a></h3><p>Полное открытие Трёхсот Изначальных Систем Культивации даёт каждому практику достаточное пространство выбора. Практик может найти наиболее подходящий путь в богатой библиотеке систем согласно своим чертам. Цивилизация также создала «Механизм оценки совместимости систем», предоставляющий индивидуальные рекомендации по выбору системы через сеть якорей, но окончательный выбор всегда остаётся за практиком.</p><h3 id="_4-2-ресурсная-поддержка" tabindex="-1">4.2 Ресурсная поддержка <a class="header-anchor" href="#_4-2-ресурсная-поддержка" aria-label="Permalink to &quot;4.2 Ресурсная поддержка&quot;">​</a></h3><p>Система Подряда, Связанного с Результатом, и базовая система гарантий обеспечивают каждому практику получение базовых ресурсов культивации. Для практиков с особыми потребностями (например, особые ресурсные потребности из-за расовых черт) цивилизация предоставляет целевое распределение ресурсов. Цель — устранить тревоги практиков, позволив им сосредоточиться на собственном эволюционном ритме.</p><h3 id="_4-3-наставническая-поддержка" tabindex="-1">4.3 Наставническая поддержка <a class="header-anchor" href="#_4-3-наставническая-поддержка" aria-label="Permalink to &quot;4.3 Наставническая поддержка&quot;">​</a></h3><p>Межрасовая сеть наставников предоставляет практикам руководство и ответы на вопросы. Роль наставника — «проводник», а не «контролёр»; наставник может делиться опытом, указывать на проблемы, давать советы, но не может заставлять практика практиковать по-своему. Система подчёркивает «эвристическое обучение», зажигающее способность практика к автономному мышлению.</p><h3 id="_4-4-средовая-поддержка" tabindex="-1">4.4 Средовая поддержка <a class="header-anchor" href="#_4-4-средовая-поддержка" aria-label="Permalink to &quot;4.4 Средовая поддержка&quot;">​</a></h3><p>Цивилизация стремится создать среду культивации, поощряющую исследование, терпимую к различиям и уважающую выбор. Практики могут свободно пробовать разные методы культивации, не опасаясь дискриминации за «неосновные» пути. Цивилизация также создала «Механизм наград за инновации в культивации», поощряя практиков к инновациям и индивидуальной переработке существующих систем.</p><h2 id="v-обработка-особых-случаев" tabindex="-1">V. Обработка особых случаев <a class="header-anchor" href="#v-обработка-особых-случаев" aria-label="Permalink to &quot;V. Обработка особых случаев&quot;">​</a></h2><p>Закон в целом применим повсеместно, но требует особой обработки в следующих случаях:</p><ul><li><strong>Несовершеннолетние практики</strong>: для тех, кто ещё не обладает полной автономной способностью суждения, их опекуны или расовые образовательные учреждения предоставляют направляющие планы культивации, но по мере умственного взросления их автономные права выбора постепенно расширяются</li><li><strong>Лица с повреждённым разумом</strong>: для индивидов с повреждённым по разным причинам разумом, временно неспособных к автономной культивации, цивилизация предоставляет лечение и реабилитацию, и после восстановления автономных способностей они следуют принципу самостоятельного роста</li><li><strong>Сошедшие с пути</strong>: для индивидов, отклонившихся в культивации или потерявших рассудок, цивилизация предоставляет принудительное вмешательство и спасение, но это медицинская помощь, а не эволюционное вмешательство; цель спасения — восстановить их способность к автономной эволюции</li><li><strong>Лица с опасными тенденциями</strong>: для индивидов, чьё направление культивации явно нарушает принцип анти-хищничества и может причинить серьёзный вред себе или другим, цивилизация имеет право ограничивать и направлять их, но по возможности через образование и общение, а не принудительные средства</li></ul><h2 id="vi-цивилизационное-значение-закона" tabindex="-1">VI. Цивилизационное значение закона <a class="header-anchor" href="#vi-цивилизационное-значение-закона" aria-label="Permalink to &quot;VI. Цивилизационное значение закона&quot;">​</a></h2><p>Закон имеет глубокое значение для симбиотической цивилизации:</p><p>Первое — он защищает разнообразие эволюции. Когда каждая жизнь эволюционирует по своему ритму и пути, во вселенной возникают богатые и красочные эволюционные формы; это разнообразие — важный ресурс общего вознесения вселенной.</p><p>Второе — он повышает качество эволюции. Самостоятельная эволюция имеет прочный фундамент и чистый Исток; уровни практиков более стабильны, а потенциал прорыва к высшим уровням больше.</p><p>Третье — он защищает достоинство жизни. Каждая жизнь — хозяин своей эволюции, а не инструмент, управляемый другими. Эта автономия — ядро достоинства жизни.</p><p>Четвёртое — он зажигает креативность эволюции. Когда практики больше не связаны едиными стандартами и ритмами, они с большей вероятностью исследуют совершенно новые эволюционные пути и методы, внося вклад в постоянную оптимизацию Трёхсот Систем.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Закон Самостоятельного Роста и Саморазвития — глубокое уважение Симбиотической Цивилизации Якоря к законам эволюции жизни. Он говорит нам: истинная эволюция — не результат, навязанный внешними силами, а рост самой жизни изнутри наружу. Все институциональные проекты симбиотической цивилизации в конечном счёте существуют, чтобы создать хорошую среду, в которой каждая жизнь может расти самостоятельно, позволяя каждой жизни стать лучшей версией себя по собственному ритму.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Система гарантий «Путь для Каждого»)</li><li>14-修炼境界统一划分 (Единое деление уровней культивации)</li><li>37-共生教育体系 (Симбиотическая образовательная система)</li></ul>',38)])])}const u=a(i,[["render",h]]);export{_ as __pageData,u as default};
